/// <summary>
/// Extension of  WrkCtrResourceGroup table
/// </summary>
[ExtensionOf(tableStr(WrkCtrResourceGroup))]
final class NDXWrkCtrResourceGroup_tbl_Extension
{
}

Method.Source:
/// <summary>
/// find record by WrkCtrTable records
/// </summary>
/// <param name = "_wrkCtrTable">WrkCtrTable record</param>
/// <param name = "_update">for update</param>
/// <returns>WrkCtrResourceGroup record</returns>
static public WrkCtrResourceGroup findByWrkCtrTable(WrkCtrTable _wrkCtrTable, boolean _update = false)
{
    WrkCtrResourceGroup lWrkCtrResourceGroup;
    WrkCtrResourceGroupResource lWrkCtrResourceGroupResource;

    lWrkCtrResourceGroup.selectForUpdate(_update);

    select firstonly lWrkCtrResourceGroup
        join lWrkCtrResourceGroupResource where lWrkCtrResourceGroupResource.ResourceGroup == lWrkCtrResourceGroup.RecId
        &&  lWrkCtrResourceGroupResource.WrkCtrId == _wrkCtrTable.WrkCtrId;

    return lWrkCtrResourceGroup;
}

/// <summary>
/// Find a resource group
/// </summary>
/// <param name = "_wrkCtrId">wrkCtrlId</param>
/// <param name = "_update">for update</param>
/// <returns></returns>
static public WrkCtrResourceGroup findResourceGroup(WrkCtrId _wrkCtrId, boolean _update = false)
{
    WrkCtrResourceGroup lWrkCtrResourceGroup;
    WrkCtrResourceGroupResource lWrkCtrResourceGroupResource;

    lWrkCtrResourceGroup.selectForUpdate(_update);

    //Check if wrkCtrId represents allready a resource group
    select lWrkCtrResourceGroup
        where lWrkCtrResourceGroup.WrkCtrId == _wrkCtrId;

    //if it is not a group then look if it is a resourse that is releted to a group 
    if(!lWrkCtrResourceGroup)
    {
        select firstonly lWrkCtrResourceGroup
            join lWrkCtrResourceGroupResource where lWrkCtrResourceGroupResource.ResourceGroup == lWrkCtrResourceGroup.RecId
                &&  lWrkCtrResourceGroupResource.WrkCtrId == _wrkCtrId;
    }
    return lWrkCtrResourceGroup;
}
